"""Русские объяснения, числовые примеры и проверяемые учебные рецепты CML-lab."""

from typing import Any


SK = "https://scikit-learn.org/1.8/"


def source(title: str, url: str, *, language: str = "en") -> dict[str, str]:
    return {"title": title, "url": url, "kind": "primary", "language": language}


def api(name: str, module: str) -> dict[str, str]:
    return source(f"scikit-learn 1.8: {name}", f"{SK}modules/generated/sklearn.{module}.{name}.html")


def guide(title: str, page: str) -> dict[str, str]:
    return source(title, SK + page)


LEAKAGE = guide("scikit-learn: утечка данных", "common_pitfalls.html")
CV = guide("scikit-learn: проверка на других строках", "modules/cross_validation.html")
ISLP = source("Авторы открытого учебника ISLP: статистическое обучение", "https://www.statlearning.com/")
ESL = source("Hastie, Tibshirani, Friedman: The Elements of Statistical Learning", "https://hastie.su.domains/ElemStatLearn/download.html")
FPP = source("Hyndman, Athanasopoulos: Forecasting, Principles and Practice", "https://otexts.com/fpp3/tscv.html")
XGB_RANK = source("XGBoost: обучение ранжированию и группы запросов", "https://xgboost.readthedocs.io/en/stable/tutorials/learning_to_rank.html")
IMB = source("imbalanced-learn: выборка внутри обучения", "https://imbalanced-learn.org/stable/common_pitfalls.html")


def help_entry(key: str, label: str, summary: str, example: str, lesson_id: str,
               *, details: str | None = None, effects: tuple[str, ...] = (),
               cautions: tuple[str, ...] = ()) -> dict[str, Any]:
    record = next(item for item in LESSONS if item["id"] == lesson_id) if lesson_id in {item["id"] for item in LESSONS} else None
    return {"key": key, "label": label, "summary": summary, "details": details or summary,
            "example": example, "lesson_id": lesson_id,
            "sources": record["sources"] if record else [LEAKAGE, CV],
            "effects": list(effects), "cautions": list(cautions)}


def preset(algorithm: str, task: str = "classification", *, name: str = "load_iris",
           kind: str = "sklearn", params: dict[str, Any] | None = None,
           data_params: dict[str, Any] | None = None,
           experiment: dict[str, Any] | None = None) -> dict[str, Any]:
    spec: dict[str, Any] = {
        "task": task, "algorithm_id": algorithm, "params": params or {}, "seed": 42,
        "preprocessing": {"steps": [], "resampling": {"method": "none"}},
        "validation": {"strategy": "stratified_kfold" if task == "classification" else "kfold", "folds": 3},
    }
    if task in {"clustering", "anomaly", "reduction"}:
        spec["validation"] = {"strategy": "none"}
    spec.update(experiment or {})
    return {"dataset": {"kind": kind, "name": name, "params": data_params or {}}, "experiment": spec}


def lesson(identifier: str, title: str, summary: str, example: str,
           action: str, effect: str, mistakes: list[str], exercise: str,
           sources: list[dict[str, str]], *, tasks: tuple[str, ...],
           families: tuple[str, ...] = (), runnable: dict[str, Any] | None = None,
           formula: str | None = None, level: str = "beginner") -> dict[str, Any]:
    sections = [
        {"title": "Пример с числами", "text": example},
        {"title": "Что меняешь в настройках", "text": action},
        {"title": "Как проверить результат", "text": effect},
        {"title": "Где можно ошибиться", "text": "\n\n".join(mistakes)},
    ]
    if formula:
        sections[0]["formula"] = formula
    return {
        "id": identifier, "title": title, "summary": summary, "example": example,
        "sections": sections, "exercise": exercise, "common_mistakes": mistakes,
        "sources": sources, "tasks": list(tasks), "families": list(families),
        "level": level, "preset": runnable,
    }


