def parameter_help(identifier: str, family: str, key: str, namespace: str) -> dict[str, Any]:
    if key == "method" and namespace == "preprocessing":
        examples = {
            "numeric.scale": "Standard: при среднем 100 и std=20 значение 140 дает 2. Normalize нормирует каждую строку целиком, а не каждый столбец.",
            "numeric.power": "Signed log1p превращает 9 в log(10), −9 в −log(10). Box–Cox требует положительных входов.",
            "selection.univariate": "F оценивает отдельную линейную связь, взаимная информация может учитывать нелинейную; chi2 требует неотрицательного входа.",
        }
        return {"summary": "Выбор конкретного вычислительного правила этапа.", "details": "Порядок шага и выбранные столбцы сохраняются в рецепте.", "example": examples.get(identifier, "Сравни два доступных способа на одном разрезе и сверяй фактические выходные значения в предпросмотре.")}
    if namespace == "preprocessing" and identifier.endswith("impute") and key == "n_neighbors":
        return {"summary": "Число похожих обучающих строк для заполнения числового пропуска.", "details": "KNNImputer усредняет доступные значения выбранных соседей. Масштаб столбцов влияет на их близость.", "example": "Для пропущенного дохода и трех соседей со значениями 10,20,30 замена при равных весах равна 20."}
    if namespace == "preprocessing" and identifier == "numeric.impute" and key == "max_iter":
        return {"summary": "Бюджет проходов итеративного заполнения пропусков.", "details": "В каждом проходе модели предсказывают отсутствующие значения выбранных столбцов по другим. Это бюджет заполнителя, не бюджет основной модели.", "example": "max_iter=10 разрешает до десяти проходов; критерий остановки может закончить их раньше."}
    if namespace == "preprocessing" and identifier == "numeric.spline" and key == "degree":
        return {"summary": "Степень локальных полиномиальных частей сплайна.", "details": "Степень 1 дает линейные части, 3 — кубические. Узлы и степень определяют число новых столбцов, а основная модель учит их веса.", "example": "Пять узлов, степень 3 и include_bias=false дают шесть выходных столбцов на один числовой вход."}
    if key == "alpha":
        if identifier in {"multinomial_nb", "complement_nb", "bernoulli_nb", "categorical_nb"}:
            return {"summary": "Сглаживание счетов редких событий.", "details": "Добавляет псевдосчета и не дает редкому событию сразу получить нулевую вероятность.", "example": "Если слово не встречалось в классе, положительное сглаживание оставляет ему ненулевую оценку.", "cautions": ["Это не штраф Ridge по квадратам коэффициентов."]}
        if "gaussian_process" in identifier:
            return {"summary": "Добавка к диагонали обучающей ковариационной матрицы.", "details": "Может описывать шум наблюдений и стабилизировать численное решение.", "example": "При alpha=0.01 ковариационная диагональ получает добавку 0.01.", "cautions": ["Это не сила штрафа линейной модели."]}
        return {"summary": "Сила штрафа выбранной модели.", "details": "Увеличение положительного alpha повышает цену величины параметров. Нормировка функции зависит от алгоритма: у Ridge сумма ошибок, у Lasso средняя ошибка с множителем.", "example": "Сравни alpha=0.1, 1 и 10 только внутри одной модели при одинаковых строках обучения.", "cautions": ["Одинаковый alpha у разных алгоритмов не означает одинаковую регуляризацию."]}
    if key == "gamma":
        if identifier in {"scad", "mcp"}:
            return {"summary": "Форма невыпуклого штрафа.", "details": "Определяет, как штраф меняет воздействие на большие коэффициенты. Это не локальность RBF-ядра.", "example": "Меняй gamma при одном alpha и проверяй коэффициенты, функцию и проверочную ошибку.", "cautions": ["Решатель невыпуклой задачи не гарантирует глобальный минимум."]}
        return {"summary": "Локальность влияния точки в подходящем ядре.", "details": "Для RBF большая положительная gamma делает влияние точки более локальным.", "example": "Сравни gamma=0.01 и 1 при одном C после одинакового масштабирования.", "cautions": ["Числовой смысл зависит от масштаба подготовленных признаков."]}
    if key == "epsilon":
        if identifier == "huber":
            return {"summary": "Порог стандартизованного остатка Huber.", "details": "Пока |остаток/масштаб| не больше epsilon, ошибка квадратичная; дальше — линейная.", "example": "epsilon=1.35 относится к остатку, деленному на оцененный масштаб, а не к 1.35 рубля.", "cautions": ["Для Huber epsilon должен быть не меньше 1."]}
        if identifier == "adaptive_lasso":
            return {"summary": "Малая добавка перед вычислением адаптивного веса.", "details": "Защищает от деления на ноль у малого первичного коэффициента.", "example": "При нулевом первичном весе положительный epsilon ограничивает адаптивный штраф."}
        return {"summary": "Ширина полосы ошибок без соответствующего штрафа у SVR.", "details": "Задана в исходных единицах числовой цели.", "example": "При цене в рублях epsilon=1000 дает допуск 1000 рублей.", "cautions": ["Это не порог стандартизованного остатка Huber."]}
    if key == "learning_rate" and ("sgd" in identifier or identifier == "perceptron"):
        return {"summary": "Расписание шага обновления весов.", "details": "constant оставляет выбранный шаг, invscaling уменьшает его по степенному правилу, другие варианты используют свой контракт.", "example": "eta0 задает начальную величину для подходящего расписания; learning_rate выбирает правило ее изменения."}
    return PARAMETERS.get(key, {})


